'use client'

import { useState, useRef, useEffect } from 'react'
import { Send, X, ArrowLeft } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { AIMobileSheet } from './ai-mobile-sheet'
import { PRODUCTS } from '@/lib/mock-data'
import { CHAT_PRODUCTS, getChatProductsByCategory } from '@/lib/chat-products'
import { ChatProductCard } from './chat-product-card'
import { TypingIndicator } from './typing-indicator'
import { useCartStore } from '@/lib/store'
import type { ChatProduct } from '@/lib/chat-products'

interface Message {
  id: string
  type: 'user' | 'ai'
  content: string
  products?: typeof PRODUCTS
  chatProducts?: ChatProduct[]
}

const QUICK_SUGGESTIONS = [
  { label: 'How to Order', preset: 'How to Order' },
  { label: 'Payment Methods', preset: 'Payment Methods' },
  { label: 'Shipping Info', preset: 'Shipping Info' },
  { label: 'Return Policy', preset: 'Return Policy' },
  { label: 'Track My Order', preset: 'Track My Order' },
]

export function FloatingAIWidget() {
  const [isMobile, setIsMobile] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      type: 'ai',
      content: "Hi 👋 I'm your ZORROW AI fashion mentor. Need outfit ideas or styling help?",
    },
  ])
  const [input, setInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const addToCart = useCartStore((state) => state.addToCart)

  // Detect mobile on mount and window resize
  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 768)
    }
    checkMobile()
    window.addEventListener('resize', checkMobile)
    return () => window.removeEventListener('resize', checkMobile)
  }, [])

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const getProductSuggestions = (message: string): typeof PRODUCTS => {
    const lower = message.toLowerCase()

    if (lower.includes('trending')) {
      return PRODUCTS.slice(0, 3)
    }

    if (lower.includes('outfit') && lower.includes('party')) {
      return PRODUCTS.filter((p) => ['Women', 'Unisex'].includes(p.category)).slice(0, 3)
    }

    if (lower.includes('outfit') || lower.includes('what should')) {
      return PRODUCTS.filter((p) => p.price < 3000).slice(0, 3)
    }

    if (lower.includes('2000') || lower.includes('under')) {
      return PRODUCTS.filter((p) => p.price < 2000)
    }

    return PRODUCTS.slice(0, 3)
  }

  const getAIResponse = (message: string): { response: string; products: typeof PRODUCTS; chatProducts: ChatProduct[] } => {
    const lower = message.toLowerCase()
    let chatProducts: ChatProduct[] = []
    let products: typeof PRODUCTS = []
    const cartItems = useCartStore.getState().items
    const wishlistItems = useCartStore.getState().wishlist

    // Handle help requests
    if (lower.includes('how to order')) {
      return {
        response:
          'Ordering on ZORROW X is easy:\n1. Browse products in Feed or Explore\n2. Tap ❤️ to save items to Wishlist\n3. Add items to Cart\n4. Open Cart and tap Checkout\n5. Enter address & choose payment\n6. Place your order 🎉',
        products: [],
        chatProducts: [],
      }
    }

    if (lower.includes('payment')) {
      return {
        response: 'We support:\n• UPI\n• Credit/Debit Cards\n• Razorpay Secure Payments\n• Cash on Delivery',
        products: [],
        chatProducts: [],
      }
    }

    if (lower.includes('shipping')) {
      return {
        response: 'Shipping ₹99 across India.\nFree shipping on orders above ₹1999.\nDelivery time: 3–7 days.',
        products: [],
        chatProducts: [],
      }
    }

    if (lower.includes('return')) {
      return {
        response: 'Easy 7-day returns for unused items.\nRefunds processed quickly after pickup.',
        products: [],
        chatProducts: [],
      }
    }

    if (lower.includes('track')) {
      return {
        response: 'You can track orders from Profile → Order History.',
        products: [],
        chatProducts: [],
      }
    }

    // AI sales assistant behavior
    if (cartItems.length > 0 && (lower.includes('ready') || lower.includes('checkout') || lower.includes('order'))) {
      return {
        response: 'Your cart looks great 👀 Ready to checkout?',
        products: [],
        chatProducts: [],
      }
    }

    if (wishlistItems.length > 0 && (lower.includes('wishlist') || lower.includes('saved') || lower.includes('favorite'))) {
      return {
        response: 'Your wishlist has some amazing picks. Want to add them to cart?',
        products: PRODUCTS.filter((p) => wishlistItems.includes(p.id)).slice(0, 4),
        chatProducts: [],
      }
    }

    // Handle shoes
    if (lower.includes('shoe')) {
      products = PRODUCTS.filter((p) => p.category === 'Shoes')
      return {
        response: 'Here are some premium shoes perfect for streetwear! Check out our sneakers and casual shoes. 👟',
        products,
        chatProducts,
      }
    }

    // Handle caps
    if (lower.includes('cap') || lower.includes('hat')) {
      products = PRODUCTS.filter((p) => p.category === 'Caps')
      return {
        response: 'Fresh caps to complete your look! Perfect for any streetwear fit. 🧢',
        products,
        chatProducts,
      }
    }

    // Handle accessories
    if (lower.includes('accessorie') || lower.includes('watch') || lower.includes('sunglasses') || lower.includes('bag')) {
      products = PRODUCTS.filter((p) => p.category === 'Accessories')
      return {
        response: 'Amazing accessories to elevate your style! From watches to sunglasses and bags. ✨',
        products,
        chatProducts,
      }
    }

    // Handle gadgets
    if (lower.includes('gadget') || lower.includes('earbuds') || lower.includes('fitness') || lower.includes('tech')) {
      products = PRODUCTS.filter((p) => p.category === 'Gadgets')
      return {
        response: 'Check out our latest tech gadgets! Smart watches, earbuds, and fitness bands. 🎧',
        products,
        chatProducts,
      }
    }

    // Handle men's fashion
    if (lower.includes("men's") || (lower.includes('men') && !lower.includes('women'))) {
      products = PRODUCTS.filter((p) => p.category === 'Men')
      return {
        response: "Perfect! Here are our trending men's pieces. From hoodies to jackets and pants. 👕",
        products,
        chatProducts,
      }
    }

    // Handle women's fashion
    if (lower.includes("women's") || (lower.includes('women') && !lower.includes('men'))) {
      products = PRODUCTS.filter((p) => p.category === 'Women')
      return {
        response: "Great! Here are our trending women's pieces. Oversized hoodies, jackets, and more. 👗",
        products,
        chatProducts,
      }
    }

    // Handle trending
    if (lower.includes('trending')) {
      products = PRODUCTS.filter((p) => p.rating && p.rating >= 4.7)
      return {
        response: 'Check out these trending pieces right now! They are super popular and selling fast. 🔥',
        products,
        chatProducts: [],
      }
    }

    // Handle outfit building
    if (lower.includes('outfit')) {
      products = PRODUCTS.slice(0, 6)
      return {
        response: 'Perfect! Here are some amazing pieces to create your outfit. Mix and match to get the vibe you want! ✨',
        products,
        chatProducts: [],
      }
    }

    // Handle budget
    if (lower.includes('2000') || lower.includes('budget') || lower.includes('under')) {
      products = PRODUCTS.filter((p) => p.price < 2000)
      return {
        response: 'Great! Here are some affordable options without compromising on style. 💯',
        products,
        chatProducts: [],
      }
    }

    // Default response with mixed products
    products = PRODUCTS.slice(0, 6)
    return {
      response: 'These pieces would look amazing on you! Would you like to add any to your cart? 🛍️',
      products,
      chatProducts: [],
    }
  }

  const handleSendMessage = (text?: string) => {
    const messageText = text || input
    if (!messageText.trim()) return

    const userMessage: Message = {
      id: Date.now().toString(),
      type: 'user',
      content: messageText,
    }

    setMessages((prev) => [...prev, userMessage])
    setInput('')
    setIsLoading(true)

    // Simulate 1-2 second typing delay for realistic feel
    setTimeout(() => {
      const { response, products, chatProducts } = getAIResponse(messageText)
      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        type: 'ai',
        content: response,
        products: products.length > 0 ? products : undefined,
        chatProducts: chatProducts.length > 0 ? chatProducts : undefined,
      }
      setMessages((prev) => [...prev, aiMessage])
      setIsLoading(false)
    }, 1200)
  }

  return (
    <>
      {/* Floating AI Button - Mobile Only */}
      {isMobile && !isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          style={{
            position: 'fixed',
            bottom: '90px',
            right: '20px',
            zIndex: 9999,
            width: '64px',
            height: '64px',
            borderRadius: '50%',
            background: 'linear-gradient(to bottom right, rgba(0,150,150,1), rgba(0,150,150,0.6))',
            border: 'none',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
            transition: 'all 0.3s',
          }}
          onMouseEnter={(e) => {
            (e.currentTarget).style.transform = 'scale(1.1)'
            (e.currentTarget).style.boxShadow = '0 25px 50px rgba(0,150,150,0.4)'
          }}
          onMouseLeave={(e) => {
            (e.currentTarget).style.transform = 'scale(1)'
            (e.currentTarget).style.boxShadow = '0 20px 40px rgba(0,0,0,0.4)'
          }}
          aria-label="Open AI chat"
        >
          <img
            src="/logo.png"
            alt="ZORROW AI"
            style={{
              width: '32px',
              height: '32px',
              objectFit: 'contain',
            }}
          />
        </button>
      )}

      {/* Mobile: Bottom Sheet - Only show on mobile when opened */}
      {isMobile && isOpen && (
        <AIMobileSheet isOpen={true} onClose={() => setIsOpen(false)} />
      )}

      {/* Desktop: Sidebar Chat Panel */}
      {!isMobile && (
        <div className="h-full w-full rounded-3xl flex flex-col overflow-hidden">
          {/* Header */}
          <div 
            className="p-4 border-b flex items-center justify-between"
            style={{
              background: 'rgba(0,150,150,0.1)',
              borderColor: 'rgba(0,150,150,0.3)'
            }}
          >
            <div className="flex items-center gap-3">
              <img
                src="https://hebbkx1anhila5yf.public.blob.vercel-storage.com/LOGO%20BLACK-h1nVhNKIhTXz5sNvtj75J9us3BZuML.png"
                alt="ZORROW AI"
                className="w-8 h-8"
              />
              <div>
                <p style={{ fontSize: '14px', fontWeight: 'bold', color: 'white', margin: 0 }}>ZORROW AI</p>
                <p style={{ fontSize: '12px', color: 'rgba(0,150,150,0.8)', margin: 0 }}>Fashion Mentor</p>
              </div>
            </div>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4" style={{ scrollBehavior: 'smooth' }}>
            {messages.map((msg) => (
              <div key={msg.id}>
                <div
                  style={{
                    display: 'flex',
                    justifyContent: msg.type === 'user' ? 'flex-end' : 'flex-start',
                    marginBottom: '8px'
                  }}
                >
                  <div
                    style={{
                      maxWidth: '280px',
                      padding: '12px 16px',
                      borderRadius: '18px',
                      background: msg.type === 'user' 
                        ? 'rgba(0,150,150,0.8)' 
                        : 'rgba(255,255,255,0.1)',
                      color: msg.type === 'user' ? 'white' : 'white',
                      fontSize: '14px',
                      borderBottomRightRadius: msg.type === 'user' ? '4px' : '18px',
                      borderBottomLeftRadius: msg.type === 'user' ? '18px' : '4px',
                    }}
                  >
                    <p style={{ margin: 0 }}>{msg.content}</p>
                  </div>
                </div>

                {/* Chat Product suggestions (new format) */}
                {msg.chatProducts && msg.chatProducts.length > 0 && (
                  <div className="mt-3 flex flex-wrap gap-2">
                    {msg.chatProducts.map((product) => (
                      <ChatProductCard key={product.id} product={product} />
                    ))}
                  </div>
                )}

                {/* Product suggestions (old format for main products) */}
                {msg.products && msg.products.length > 0 && (
                  <div className="mt-3 space-y-2">
                    {msg.products.map((product) => (
                      <div
                        key={product.id}
                        className="bg-white/5 rounded-lg p-3 border border-primary/20 hover:border-primary/40 transition-colors"
                      >
                        <div className="flex gap-3">
                          <img
                            src={product.image}
                            alt={product.name}
                            className="w-16 h-16 rounded object-cover"
                          />
                          <div className="flex-1 text-xs">
                            <p className="text-white font-semibold line-clamp-2">{product.name}</p>
                            <p className="text-primary">₹{product.price}</p>
                            <button
                              onClick={() =>
                                addToCart(product, 1)
                              }
                              className="mt-1 text-primary hover:text-primary/80 font-semibold text-xs"
                            >
                              Add to Cart
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <TypingIndicator />
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Quick suggestions (show only if few messages) */}
          {messages.length <= 2 && (
            <div 
              style={{
                padding: '12px 16px',
                borderTop: '1px solid rgba(0,150,150,0.3)',
                display: 'flex',
                gap: '8px',
                overflowX: 'auto',
                scrollBehavior: 'smooth'
              }}
            >
              {QUICK_SUGGESTIONS.map((suggestion) => (
                <button
                  key={suggestion.label}
                  onClick={() => handleSendMessage(suggestion.preset)}
                  style={{
                    whiteSpace: 'nowrap',
                    padding: '6px 12px',
                    fontSize: '12px',
                    background: 'rgba(0,150,150,0.2)',
                    border: '1px solid rgba(0,150,150,0.4)',
                    color: 'rgba(0,150,150,1)',
                    borderRadius: '20px',
                    cursor: 'pointer',
                    transition: 'all 0.2s'
                  }}
                  onMouseEnter={(e) => {
                    (e.target as HTMLButtonElement).style.background = 'rgba(0,150,150,0.4)'
                    (e.target as HTMLButtonElement).style.borderColor = 'rgba(0,150,150,0.6)'
                  }}
                  onMouseLeave={(e) => {
                    (e.target as HTMLButtonElement).style.background = 'rgba(0,150,150,0.2)'
                    (e.target as HTMLButtonElement).style.borderColor = 'rgba(0,150,150,0.4)'
                  }}
                  disabled={isLoading}
                >
                  {suggestion.label}
                </button>
              ))}
            </div>
          )}

          {/* Input Area */}
          <form
            onSubmit={(e) => {
              e.preventDefault()
              handleSendMessage()
            }}
            style={{
              borderTop: '1px solid rgba(0,150,150,0.3)',
              padding: '12px 16px',
              display: 'flex',
              gap: '8px',
              alignItems: 'center'
            }}
          >
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask me..."
              style={{
                flex: 1,
                height: '40px',
                fontSize: '14px',
                background: 'rgba(255,255,255,0.05)',
                border: '1px solid rgba(0,150,150,0.3)',
                borderRadius: '12px',
                padding: '8px 12px',
                color: 'white',
                outline: 'none',
                transition: 'all 0.2s'
              }}
              onFocus={(e) => {
                e.currentTarget.style.borderColor = 'rgba(0,150,150,0.6)'
                e.currentTarget.style.background = 'rgba(255,255,255,0.1)'
              }}
              onBlur={(e) => {
                e.currentTarget.style.borderColor = 'rgba(0,150,150,0.3)'
                e.currentTarget.style.background = 'rgba(255,255,255,0.05)'
              }}
              disabled={isLoading}
            />
            <button
              type="submit"
              style={{
                height: '40px',
                width: '40px',
                padding: 0,
                background: 'rgba(0,150,150,0.8)',
                border: 'none',
                borderRadius: '12px',
                color: 'white',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                transition: 'all 0.2s',
                opacity: isLoading || !input.trim() ? 0.5 : 1
              }}
              onMouseEnter={(e) => {
                if (!isLoading && input.trim()) {
                  (e.currentTarget).style.background = 'rgba(0,150,150,1)'
                }
              }}
              onMouseLeave={(e) => {
                (e.currentTarget).style.background = 'rgba(0,150,150,0.8)'
              }}
              disabled={isLoading || !input.trim()}
            >
              <Send className="w-4 h-4" />
            </button>
          </form>
        </div>
      )}
    </>
  )
}
